/**
 * Retorna as questões de um episódio (com gabarito — uso interno do servidor).
 */
export function getPodcastQuiz(episodeId: string): readonly PodcastQuizQuestion[] {
  return episodeQuizBank[episodeId] ?? [];
}

/**
 * Retorna as questões públicas, sem gabarito nem explicação.
 */
export function getPublicPodcastQuiz(episodeId: string) {
  return getPodcastQuiz(episodeId).map(({ correctAnswer: _correctAnswer, explanation: _explanation, ...question }) => question);
}

/**
 * Corrige as respostas no servidor. Retorna null se o episódio ou a quantidade
 * de respostas for inválida.
 */
export function gradePodcastQuiz(episodeId: string, answers: number[]) {
  const questions = getPodcastQuiz(episodeId);
  if (questions.length === 0 || answers.length !== questions.length) return null;
  const score = questions.reduce((total, question, index) => total + (answers[index] === question.correctAnswer ? 1 : 0), 0);
  return {
    score,
    totalQuestions: questions.length,
    percentage: Math.round((score / questions.length) * 100),
    review: questions.map((question, index) => ({
      id: question.id,
      correct: answers[index] === question.correctAnswer,
      correctAnswer: question.correctAnswer,
      explanation: question.explanation,
    })),
  };
}

/** Lista dos IDs de episódios com quiz disponível. */
export const podcastQuizEpisodes = Object.keys(episodeQuizBank);
